package electrolyte.greate.infrastructure.ponder;

import com.simibubi.create.foundation.ponder.CreateSceneBuilder;
import net.createmod.ponder.api.PonderPalette;
import net.createmod.ponder.api.scene.SceneBuilder;
import net.createmod.ponder.api.scene.SceneBuildingUtil;
import net.createmod.ponder.api.scene.Selection;
import net.minecraft.core.Direction;

/**
 * Ponder scenes authored by this mod rather than reused from Create.
 *
 * <p>A scene is a structure file ({@code assets/greate_remake/ponder/<id>.nbt}, generated by
 * {@code tools/gen_ponder_structures.py}) plus this program. Lang keys are
 * {@code greate_remake.ponder.<sceneId>.<header|text_N>}, where N follows the order of
 * {@code showText} calls - reordering text means renaming keys.</p>
 */
public final class GreateTierScenes {

    public static void fanTier(SceneBuilder builder, SceneBuildingUtil util) {
        CreateSceneBuilder scene = new CreateSceneBuilder(builder);
        scene.title("fan_tier", "Tiered Encased Fan");
        scene.configureBasePlate(0, 0, 7);
        scene.showBasePlate();
        scene.idle(10);

        Selection ulv = util.select().fromTo(0, 1, 1, 3, 1, 1);
        Selection lv = util.select().fromTo(0, 1, 5, 3, 1, 5);
        scene.world().showSection(ulv, Direction.DOWN);
        scene.idle(5);
        scene.world().showSection(lv, Direction.DOWN);
        scene.idle(10);

        scene.world().setKineticSpeed(ulv, 64);
        scene.world().setKineticSpeed(lv, 64);
        scene.idle(20);

        scene.overlay().showOutline(PonderPalette.RED, "ulv", util.select().position(3, 1, 1), 90);
        scene.overlay().showText(90)
                .text("The lower fan is ULV (Andesite Alloy). Blasting and smoking work, "
                        + "but washing is locked at this tier.")
                .pointAt(util.vector().centerOf(1, 1, 1))
                .placeNearTarget();
        scene.idle(100);

        scene.overlay().showOutline(PonderPalette.GREEN, "lv", util.select().position(3, 1, 5), 110);
        scene.overlay().showText(110)
                .text("Upgrade to an LV (Steel) fan and the same water is now read as a "
                        + "washing catalyst.")
                .pointAt(util.vector().centerOf(1, 1, 5))
                .placeNearTarget();
        scene.effects().indicateSuccess(util.grid().at(3, 1, 5));
        scene.idle(120);

        scene.overlay().showText(120)
                .text("Tier also caps the stress of the whole network. Washing turns crushed ore "
                        + "into purified ore via GT's ore washer recipes.")
                .pointAt(util.vector().centerOf(2, 1, 3))
                .placeNearTarget();
        scene.idle(130);

        scene.markAsFinished();
    }

    public static void beltTier(SceneBuilder builder, SceneBuildingUtil util) {
        CreateSceneBuilder scene = new CreateSceneBuilder(builder);
        scene.title("belt_tier", "Tiered Belt Connector");
        scene.configureBasePlate(0, 0, 7);
        scene.showBasePlate();
        scene.idle(10);

        Selection matched = util.select().fromTo(1, 1, 2, 5, 1, 2);
        scene.world().showSection(matched, Direction.DOWN);
        scene.idle(10);
        scene.world().setKineticSpeed(matched, 32);
        scene.idle(15);

        scene.overlay().showOutline(PonderPalette.GREEN, "ends",
                util.select().position(1, 1, 2).add(util.select().position(5, 1, 2)), 90);
        scene.overlay().showText(90)
                .text("A belt connector joins two tiered shafts of the SAME tier.")
                .pointAt(util.vector().centerOf(1, 1, 2))
                .placeNearTarget();
        scene.idle(100);

        scene.overlay().showText(110)
                .text("Same tier: the connector builds the whole belt at once, and the belt "
                        + "scrolls as soon as the shafts turn.")
                .pointAt(util.vector().centerOf(3, 1, 2))
                .placeNearTarget();
        scene.effects().indicateSuccess(util.grid().at(3, 1, 2));
        scene.idle(120);

        Selection mismatched = util.select().fromTo(1, 1, 5, 5, 1, 5);
        scene.world().showSection(mismatched, Direction.DOWN);
        scene.idle(15);
        scene.overlay().showOutline(PonderPalette.RED, "mismatch", mismatched, 120);
        scene.overlay().showText(120)
                .text("Different tiers: the connection is refused outright - no belt, "
                        + "no half-built chain.")
                .pointAt(util.vector().centerOf(3, 1, 5))
                .placeNearTarget();
        scene.effects().indicateRedstone(util.grid().at(5, 1, 5));
        scene.idle(130);

        scene.overlay().showText(120)
                .text("Belt length is capped by belt_length in greate_remake-server.toml "
                        + "(20 blocks by default).")
                .pointAt(util.vector().centerOf(3, 1, 2))
                .placeNearTarget();
        scene.idle(130);

        scene.markAsFinished();
    }

    private GreateTierScenes() {
    }
}
